def getMaxRepetitions(s1: str, n1: int, s2: str, n2: int) -> int:
    if n1 == 0:
        return 0

    # To avoid TLE, we need to detect cycles in the pattern of s1
    count = 0
    index = 0
    seen = {}

    for i in range(n1):
        for char in s1:
            if char == s2[index]:
                index += 1
                if index == len(s2):
                    count += 1
                    index = 0

        if (i, index) in seen:
            cycle_start, cycle_count = seen[(i, index)]
            cycle_length = i - cycle_start
            cycle_repeats = (n1 - cycle_start - 1) // cycle_length
            count += cycle_repeats * (count - cycle_count)
            i += cycle_repeats * cycle_length

        seen[(i, index)] = (i, count)

    return count // n2
